window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fd5eb8e203684872"]={"versions": [{"id": "FIG-fd5eb8e203684872", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (Prozess- und Artefaktfluss im SPEM- bzw. UML-Aktivitätsstil) zur Veranschaulichung des Integrationsschritts „Link ECU Code during Post-build Time Selectable“ im Rahmen der BSW- und ECU-Kompilierung und -Bindung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Link ECU Code during Post-build Time Selectable</code> (zentraler Prozessschritt / Activity)\n</li></ul>\n</li><li><strong>Eingangsartefakte («input»)</strong>:\n<ul class=\"fig-list\"><li><code>Basic Software Module Object Code</code> (Kardinalität <code>1..*</code>)\n</li><li><code>BSW Module Configuration Data Object Code</code> (Kardinalität <code>0..*</code>)\n</li></ul>\n</li><li><strong>Ausgangsartefakt («output»)</strong>:\n<ul class=\"fig-list\"><li><code>ECU Executable</code> (Kardinalität <code>1</code>)\n</li></ul>\n</li><li><strong>Werkzeug («used tool»)</strong>:\n<ul class=\"fig-list\"><li><code>Linker</code> (Hammer-Symbol zur Werkzeugassoziation)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung von mindestens einem vorkompilierten Objektcode-Modul der Basessoftware (<code>Basic Software Module Object Code</code>, <code>1..*</code>).\n</li><li>Optionale Bereitstellung vorkompilierter Konfigurationsdaten-Objektcodes (<code>BSW Module Configuration Data Object Code</code>, <code>0..*</code>), sofern Post-build-Konfigurationsstrukturen direkt mitgebunden werden.\n</li><li>Ausführung der Aktivität <code>Link ECU Code during Post-build Time Selectable</code> unter Einsatz des Linkers (<code>Linker</code>).\n</li><li>Erzeugung genau eines lauffähigen Steuergeräte-Binärimages (<code>ECU Executable</code>, <code>1</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zeigt die post-build-fähige Verlinkungsphase der Steuergeräte-Software. Da die Kardinalität von <code>BSW Module Configuration Data Object Code</code> auf <code>0..*</code> gesetzt ist, erlaubt der Ansatz das Erstellen einer Executable ohne feste Konfigurationsdaten bzw. mit flexibler Zuordnung auswählbarer Konfigurationsdatensätze zur Post-Build-Zeit. Der Standard-Linker bindet die Core-BSW-Objekte und optionale Konfigurationsdatensätze zusammen in das resultierende Binärimage.</p>"}, {"id": "FIG-3aca48fda7e3b30a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (Prozess- und Artefaktfluss im SPEM- bzw. UML-Aktivitätsstil) zur Veranschaulichung des Integrationsschritts „Link ECU Code during Post-build Time Selectable“ im Rahmen der BSW- und ECU-Kompilierung und -Bindung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität</strong>:\n<ul class=\"fig-list\"><li><code>Link ECU Code during Post-build Time Selectable</code> (zentraler Prozessschritt / Activity)\n</li></ul>\n</li><li><strong>Eingangsartefakte («input»)</strong>:\n<ul class=\"fig-list\"><li><code>Basic Software Module Object Code</code> (Kardinalität <code>1..*</code>)\n</li><li><code>BSW Module Configuration Data Object Code</code> (Kardinalität <code>0..*</code>)\n</li></ul>\n</li><li><strong>Ausgangsartefakt («output»)</strong>:\n<ul class=\"fig-list\"><li><code>ECU Executable</code> (Kardinalität <code>1</code>)\n</li></ul>\n</li><li><strong>Werkzeug («used tool»)</strong>:\n<ul class=\"fig-list\"><li><code>Linker</code> (Hammer-Symbol zur Werkzeugassoziation)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Bereitstellung von mindestens einem vorkompilierten Objektcode-Modul der Basessoftware (<code>Basic Software Module Object Code</code>, <code>1..*</code>).\n</li><li>Optionale Bereitstellung vorkompilierter Konfigurationsdaten-Objektcodes (<code>BSW Module Configuration Data Object Code</code>, <code>0..*</code>), sofern Post-build-Konfigurationsstrukturen direkt mitgebunden werden.\n</li><li>Ausführung der Aktivität <code>Link ECU Code during Post-build Time Selectable</code> unter Einsatz des Linkers (<code>Linker</code>).\n</li><li>Erzeugung genau eines lauffähigen Steuergeräte-Binärimages (<code>ECU Executable</code>, <code>1</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zeigt die post-build-fähige Verlinkungsphase der Steuergeräte-Software. Da die Kardinalität von <code>BSW Module Configuration Data Object Code</code> auf <code>0..*</code> gesetzt ist, erlaubt der Ansatz das Erstellen einer Executable ohne feste Konfigurationsdaten bzw. mit flexibler Zuordnung auswählbarer Konfigurationsdatensätze zur Post-Build-Zeit. Der Standard-Linker bindet die Core-BSW-Objekte und optionale Konfigurationsdatensätze zusammen in das resultierende Binärimage.</p>"}], "trans": [{"from": "FIG-fd5eb8e203684872", "to": "FIG-3aca48fda7e3b30a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
